//! 🧪️ Genuine native slots retain originals under foreign, underfunded and outstanding-reader refusals.
use super::*;
fn scratch()->semio_framework_value_testing_effect_bank::EffectBank{semio_framework_value_testing_effect_bank::EffectBank::new(semio_framework_value_testing_effect_bank::Wallet::from_profile(&serde_json::json!({"items":1u64<<40,"copyBytes":1u64<<40,"capacityBytes":1u64<<40,"releaseBytes":1u64<<40,"depth":1u64<<20,"fuel":1u64<<60})))}
trait Prog{fn prog(&self)->RetainedCloneProgress;}
impl Prog for crate::ValueError{fn prog(&self)->RetainedCloneProgress{self.retained_progress()}}
impl Prog for crate::OriginalRetirementFailure{fn prog(&self)->RetainedCloneProgress{self.retained_progress()}}
type Reply<'r,F>=OriginalEffectReply<'r,RetainedCloneStep,F>;
type Done<'r,F>=OriginalEffectReplyComplete<'r,RetainedCloneStep,F>;
type OpFn<'a,F>=dyn for<'e,'r> FnMut(&mut crate::RetainedAllocationEffect<'e>,Reply<'r,F>)->Result<Done<'r,F>,ValueError>+'a;
struct Op<F>(std::marker::PhantomData<fn()->F>,semio_framework_value_control_contract::OriginalSourceTurnIdentity);
impl<F:'static> semio_framework_value_control_contract::OriginalEffectProducer for Op<F>{
 type Output=RetainedCloneStep;type Failure=F;type Context<'a,'b>=&'a mut OpFn<'b,F> where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'b:'a{Some(self.1)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut crate::RetainedAllocationEffect<'_>,r:Reply<'r,F>)->Result<Done<'r,F>,ValueError>where 'b:'a{c(e,r)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut crate::RetainedAllocationEffect<'_>,r:Reply<'r,F>)->Result<Done<'r,F>,ValueError>where 'b:'a{c(e,r)}
}
fn run<F:Prog+'static>(bank:&mut semio_framework_value_testing_effect_bank::EffectBank,grant:RetainedCloneGrant,mut operation:impl for<'e,'r> FnMut(&mut crate::RetainedAllocationEffect<'e>,Reply<'r,F>)->Result<Done<'r,F>,ValueError>)->crate::RetainedWorkOutcome<RetainedCloneStep,F>{
 let mut authority=semio_framework_value_control_contract::OriginalEffectAuthority::new(Op::<F>(std::marker::PhantomData,bank.source_witness().identity()));let units=bank.wallet().remaining_work();let before_work=*bank.wallet().original_work();let(mut action,mut output)=(None,None);let mut context:&mut OpFn<'_,F>=&mut operation;let mut done=false;
 for _ in 0..128{let(poll,_)=bank.run(grant,units,|effect|{let before=effect.performed_boundary();let ready=authority.drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_since(before).unwrap();if ready{crate::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{crate::RetainedWorkPoll::Pending{work}}});assert_ne!(bank.take_admitted(),Some(false));if matches!(poll,crate::RetainedWorkPoll::Pending{..}){continue}done=true;break}
 assert!(done,"original slot action exceeded its finite bound");let work=before_work-*bank.wallet().original_work();
 let demand=semio_framework_value_control_contract::OriginalEffectAuthority::<Op<F>>::transfer_reply_demand().unwrap();let tg=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()};
 let(poll,_)=bank.run(tg,1,|effect|crate::RetainedWorkPoll::Complete(authority.transfer_reply_into(&context,&mut action,&mut output,effect)));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("original slot reply transfer pending")};turn.result.unwrap().unwrap();let _=bank.take_admitted();
 assert!(authority.into_producer().is_ok());crate::RetainedWorkOutcome{result:output.take().unwrap(),work}
}

fn work(payload_bytes:usize)->usize{static POLICY:std::sync::OnceLock<(usize,usize)>=std::sync::OnceLock::new();let(per_byte,fixed)=*POLICY.get_or_init(||{let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();(usize::try_from(law["policy"]["stepsPerPayloadByte"].as_u64().unwrap()).unwrap(),usize::try_from(law["policy"]["fixedSteps"].as_u64().unwrap()).unwrap())});payload_bytes.checked_add(1).and_then(|bytes|bytes.checked_mul(per_byte)).and_then(|steps|steps.checked_add(fixed)).expect("original slot finite fixture work overflow")}
fn tick(remaining:&mut usize){*remaining=remaining.checked_sub(1).expect("original slot exhausted finite fixture work before terminal custody");}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=65536,"native slot turn exceeds the original physical policy: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
#[test]
fn original_slot_preserves_native_payload_and_waits_for_every_projected_reader(){
 let mut slot_bank=scratch();
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["policy"]["maximumItems"],1);assert_eq!(law["policy"]["owningProjection"],true);for row in law["workCases"].as_array().unwrap(){assert_eq!(work(usize::try_from(row["payloadBytes"].as_u64().unwrap()).unwrap()),usize::try_from(row["expectedSteps"].as_u64().unwrap()).unwrap());}
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default());
 let mut original=RetainedOriginalSlot::new("original α\0😀".repeat(8192));let mut remaining=work(original.get().len());let pointer=original.get().as_ptr();let key=original.key();let foreign=RetainedOriginalSlot::new(String::new()).key();assert!(original.demands(foreign,4096).is_err());
 while original.borrow(key).is_err(){tick(&mut remaining);let d=original.demands(key,4096).unwrap();for axis in 0..5{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,denied,|effect,reply|original.advance_read_into(key,&factory,effect,reply)).result.unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(original.get().as_ptr(),pointer);}
  let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|original.advance_read_into(key,&factory,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 let mut projection=semio_framework_value_retained_clone::RetainedOwnedProjectionAdmission::<String>::default();let quote=original.retain_read_demand(key,&projection).unwrap();assert!(original.retain_read_demand(foreign,&projection).is_err());let identity=original.borrow(key).unwrap().source_identity();for g in [RetainedCloneGrant{maximum_items:0,..grant(quote)},RetainedCloneGrant{maximum_depth:0,..grant(quote)}]{let(result,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|original.retain_read_into(key,&mut projection,effect,reply)));assert_eq!(result.work,0);assert_eq!(result.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert!(!projection.bound_close_available());assert_eq!(original.borrow(key).unwrap().source_identity(),identity);assert_eq!(original.get().as_ptr(),pointer);}let(result,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(quote),|effect,reply|original.retain_read_into(key,&mut projection,effect,reply)));let progress=result.result.unwrap().progress();assert!(progress.fits(grant(quote)));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert!(projection.bound_close_available());assert_eq!(original.get().as_ptr(),pointer);
 let mut withdrawn=None;let(refused,heap)=crate::observe_retirement_allocations(||original.take_original(key,&mut withdrawn,grant(RetainedOriginalSlot::<String>::transfer_demand())));assert!(refused.is_err());assert!(withdrawn.is_none());assert_eq!(heap,(0,0));
 let mut next=Some("next".to_string());let next_error=original.replace(&mut next,grant(RetainedOriginalSlot::<String>::replace_demand())).unwrap_err();assert_eq!(next_error.kind,ValueRefusalKind::InvariantViolated);assert_eq!(next.as_deref(),Some("next"));assert_eq!(original.get().as_ptr(),pointer);let mut returned=None;
 for _ in 0..8{let d=original.return_demands(key,4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|original.return_read_into(key,&mut returned,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(returned.is_none());assert_eq!(original.get().as_ptr(),pointer);}
 for _ in 0..10000{if projection.terminal_is_empty(){break;}let d=projection.close_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|projection.close_into(4096,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(projection.terminal_is_empty());
 for _ in 0..10000{if !original.has_read(){break;}let d=original.return_demands(key,4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|original.return_read_into(key,&mut returned,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(!original.has_read());assert!(Arc::ptr_eq(returned.as_ref().unwrap(),&factory));assert_eq!(original.get().as_ptr(),pointer);
 let mut issuer=crate::FactoryAuthority::new(returned.take().unwrap());while !issuer.terminal_is_empty(){tick(&mut remaining);let d=issuer.demands(4096).unwrap();run(&mut slot_bank,grant(d),|effect,reply|issuer.step_into(4096,effect,reply)).result.unwrap();}
 let value=original.try_into_original().unwrap_or_else(|_|panic!("returned original slot remains uniquely owned"));assert_eq!(value.as_ptr(),pointer);let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){tick(&mut remaining);let d=close.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|close.step_into(4096,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
}
#[test]
fn original_slot_generation_exhaustion_refuses_before_native_exchange(){
 let mut slot_bank=scratch();let mut original=RetainedOriginalSlot::new(7u64);original.generation=u64::MAX;let key=original.key();let mut next=Some(9);let error=original.replace(&mut next,grant(RetainedOriginalSlot::<u64>::replace_demand())).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((original.get(),next,original.key()),(&7,Some(9),key));}

#[test]
fn original_slot_exchange_matches_all_independent_portable_outputs(){
 let mut slot_bank=scratch();
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for law in corpus["cases"].as_array().unwrap(){let mut slot=RetainedOriginalSlot::new(serde_json::to_string(&law["original"]).unwrap());let mut remaining=work(slot.get().len().checked_add(serde_json::to_string(&law["replacement"]).unwrap().len()).unwrap());let old_pointer=slot.get().as_ptr();let key=slot.key();let mut next=Some(serde_json::to_string(&law["replacement"]).unwrap());let next_pointer=next.as_ref().unwrap().as_ptr();let d=RetainedOriginalSlot::<String>::replace_demand();
  for axis in [0,1,4]{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1}let(result,heap)=crate::observe_retirement_allocations(||slot.replace(&mut next,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(slot.get().as_ptr(),old_pointer);assert_eq!(next.as_ref().unwrap().as_ptr(),next_pointer);assert_eq!(slot.key(),key);}
  let(result,heap)=crate::observe_retirement_allocations(||slot.replace(&mut next,grant(d)).unwrap());let(previous,p)=result.unwrap();assert_eq!(heap,(0,0));assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(p.copied_items,1);assert!(next.is_none());assert_eq!(previous.as_ptr(),old_pointer);assert_eq!(slot.get().as_ptr(),next_pointer);assert_ne!(slot.key(),key);assert_eq!(serde_json::from_str::<serde_json::Value>(slot.get()).unwrap(),law["expected"]);
  let current=slot.try_into_original().unwrap_or_else(|_|panic!("portable exchange original remains uniquely owned"));for original in [previous,current]{let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){tick(&mut remaining);let d=close.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|close.step_into(4096,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}
 }
}

static RETIRED_POINTER:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
#[derive(semio_framework_value_factory::FactoryPayloadRetirement)]
#[value(crate="semio_framework_value_factory")]
struct OriginalIssuer;
impl ArtifactOwnedValueRetirementFactory<String> for OriginalIssuer{
 fn retirement_birth_bytes(&self,value:&String)->usize{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retirement_birth_bytes(value)}
 fn retire_owned_work_demand(&self,value:&String)->Result<u64,crate::ValueError>{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retire_owned_work_demand(value)}
 fn retire_owned_demands(&self,value:&String)->Result<RetirementDemand,crate::ValueError>{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retire_owned_demands(value)}
 fn retire_owned<'reply>(&self,value:&mut Option<String>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_factory::FactoryProducerReply<'reply,dyn crate::ErasedSnapshotRetirement,crate::OriginalRetirementFailure>)->semio_framework_value_factory::FactoryProducerReplyComplete<'reply,crate::OriginalRetirementFailure>{if let Some(value)=value.as_ref(){RETIRED_POINTER.store(value.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed)}semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retire_owned(value,effect,reply)}
 fn recover_retire_owned<'reply>(&self,value:&mut Option<String>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_factory::FactoryProducerReply<'reply,dyn crate::ErasedSnapshotRetirement,crate::OriginalRetirementFailure>)->semio_framework_value_factory::FactoryProducerReplyComplete<'reply,crate::OriginalRetirementFailure>{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().recover_retire_owned(value,effect,reply)}
}
#[test]
fn original_slot_retirement_returns_all_readers_then_uses_same_captured_payload_issuer(){
 let mut slot_bank=scratch();
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for state in law["policy"]["readBirthStates"].as_array().unwrap(){let prefix=state["prefix"].as_u64().unwrap();RETIRED_POINTER.store(0,std::sync::atomic::Ordering::Relaxed);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(OriginalIssuer);let mut slot=RetainedOriginalSlot::new("original cancelled α\0😀".repeat(8192));let mut remaining=work(slot.get().len());let pointer=slot.get().as_ptr()as usize;let key=slot.key();if state["state"]=="published"{assert_eq!(prefix,2);while slot.borrow(key).is_err(){tick(&mut remaining);let d=slot.demands(key,4096).unwrap();let quote=semio_framework_value_retirement::retirement::arc_custody::original::SharedOriginalPublication::<String>::work_demand()+1;let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|slot.advance_read_into(key,&factory,effect,reply)));let p=turn.result.unwrap().progress();assert!(turn.work<=u128::from(quote));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));}}else{for _ in 0..prefix{let d=slot.demands(key,4096).unwrap();run(&mut slot_bank,grant(d),|effect,reply|slot.advance_read_into(key,&factory,effect,reply)).result.unwrap();}}
  let mut projection=if prefix==2{let mut admission=semio_framework_value_retained_clone::RetainedOwnedProjectionAdmission::<String>::default();let quote=slot.retain_read_demand(key,&admission).unwrap();run(&mut slot_bank,grant(quote),|effect,reply|slot.retain_read_into(key,&mut admission,effect,reply)).result.unwrap();Some(admission)}else{None};let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(slot).map_err(|(e,_)|e).unwrap();
  for turn in 0..10000{if turn==5{if let Some(projection)=projection.as_mut(){while !projection.terminal_is_empty(){tick(&mut remaining);let d=projection.close_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|projection.close_into(4096,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}projection=None;}
   if owner.terminal_is_empty(){break;}let d=owner.next_demand(4096).unwrap();for axis in 0..5{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(result,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,denied,|effect,reply|owner.step_into(4096,effect,reply)));match result.result{Ok(step)=>assert_eq!(step.progress(),RetainedCloneProgress::default()),Err(error)=>assert_eq!(error.retained_progress(),RetainedCloneProgress::default())}assert_eq!(heap,(0,0));}
   let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|owner.step_into(4096,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if projection.is_some(){assert_eq!(RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),0);}
  }assert!(owner.terminal_is_empty());assert!(projection.is_none());assert_eq!(RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),if prefix==0{0}else{pointer});let mut issuer=crate::FactoryAuthority::new(factory);while !issuer.terminal_is_empty(){tick(&mut remaining);run(&mut slot_bank,grant(issuer.demands(4096).unwrap()),|effect,reply|issuer.step_into(4096,effect,reply)).result.unwrap();}
 }
}

#[test]
fn original_slot_withdrawal_and_installation_preserve_exact_owners_and_resident_identity(){
 let mut slot_bank=scratch();
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){for install in [false,true]{
  let mut slot=RetainedOriginalSlot::new(serde_json::to_string(&row["original"]).unwrap());let original_pointer=slot.get().as_ptr();let original_key=slot.key();let foreign=RetainedOriginalSlot::new(String::new()).key();let mut output=None;let d=RetainedOriginalSlot::<String>::transfer_demand();
  for candidate in [foreign]{let(result,heap)=crate::observe_retirement_allocations(||slot.take_original(candidate,&mut output,grant(d)));assert!(result.is_err());assert_eq!(heap,(0,0));assert!(output.is_none());}
  for axis in [0,1,4]{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1}let(result,heap)=crate::observe_retirement_allocations(||slot.take_original(original_key,&mut output,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(slot.get().as_ptr(),original_pointer);assert_eq!(slot.key(),original_key);assert!(output.is_none());}
  let(result,heap)=crate::observe_retirement_allocations(||slot.take_original(original_key,&mut output,grant(d)).unwrap());assert!(result.unwrap().fits(grant(d)));assert_eq!(heap,(0,0));assert_eq!(slot.is_empty(),row["vacant"].as_bool().unwrap());assert_eq!(serde_json::from_str::<serde_json::Value>(output.as_ref().unwrap()).unwrap(),row["withdrawn"]);assert_eq!(output.as_ref().unwrap().as_ptr(),original_pointer);assert_ne!(slot.key(),original_key);
  let mut replacement=Some(serde_json::to_string(&row["replacement"]).unwrap());let next_pointer=replacement.as_ref().unwrap().as_ptr();let empty_key=slot.key();let(stale,heap)=crate::observe_retirement_allocations(||slot.install_original(original_key,&mut replacement,grant(d)));assert!(stale.is_err());assert_eq!(heap,(0,0));
  if install{for axis in [0,1,4]{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,_=>denied.maximum_depth-=1}let(result,heap)=crate::observe_retirement_allocations(||slot.install_original(empty_key,&mut replacement,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert!(slot.is_empty());assert_eq!(slot.key(),empty_key);assert_eq!(replacement.as_ref().unwrap().as_ptr(),next_pointer);}
   let(result,heap)=crate::observe_retirement_allocations(||slot.install_original(empty_key,&mut replacement,grant(d)).unwrap());assert!(result.unwrap().fits(grant(d)));assert_eq!(heap,(0,0));assert!(replacement.is_none());assert_eq!(slot.get().as_ptr(),next_pointer);assert_eq!(serde_json::from_str::<serde_json::Value>(slot.get()).unwrap(),row["expected"]);
  }
  let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(slot).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){let d=close.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|close.step_into(4096,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
  for value in [output,replacement].into_iter().flatten(){let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();let(step,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,grant(d),|effect,reply|owner.step_into(4096,effect,reply)).result.unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}
 }}
}

#[test]
fn original_read_real_null_preserves_payload_and_direct_work_through_paid_closure(){
 let mut slot_bank=scratch();
 use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default());
 let mut original=RetainedOriginalSlot::new(law["text"].as_str().unwrap().to_owned());let pointer=original.get().as_ptr();let key=original.key();let d=original.demands(key,4096).unwrap();let g=grant(d);
 let(denied,heap)=observe(||run(&mut slot_bank,RetainedCloneGrant{maximum_items:0,..g},|effect,reply|original.advance_read_into(key,&factory,effect,reply)));assert_eq!(denied.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(heap,(0,0));assert_eq!(original.get().as_ptr(),pointer);
 let((turn,attempts),heap)=observe(||refuse(||run(&mut slot_bank,g,|effect,reply|original.advance_read_into(key,&factory,effect,reply))));assert_eq!(attempts,1);assert_eq!(turn.work,u128::from(law["nullWork"].as_u64().unwrap()));assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(original.get().as_ptr(),pointer);assert!(!original.has_read());
 let mut remaining=RetainedCloneGrant{maximum_items:law["cpuStock"].as_u64().unwrap()as usize,maximum_copy_bytes:law["copyStock"].as_u64().unwrap()as usize,maximum_capacity_bytes:law["capacityStock"].as_u64().unwrap()as usize,maximum_release_bytes:law["releaseStock"].as_u64().unwrap()as usize,maximum_depth:law["maximumDepth"].as_u64().unwrap()as usize};remaining.maximum_items-=turn.work as usize;
 let(turn,heap)=observe(||run(&mut slot_bank,g,|effect,reply|original.advance_read_into(key,&factory,effect,reply)));assert_eq!(turn.work,u128::from(law["birthWork"].as_u64().unwrap()));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));remaining.maximum_items-=turn.work as usize;remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;assert_eq!(serde_json::from_str::<serde_json::Value>(&serde_json::to_string(original.get()).unwrap()).unwrap(),law["text"]);assert_eq!(original.get().as_ptr(),pointer);
 let mut close=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let d=close.next_demand(4096).unwrap();let g=grant(d);assert!(g.maximum_items<=remaining.maximum_items&&g.maximum_copy_bytes<=remaining.maximum_copy_bytes&&g.maximum_capacity_bytes<=remaining.maximum_capacity_bytes&&g.maximum_release_bytes<=remaining.maximum_release_bytes&&g.maximum_depth<=remaining.maximum_depth);let result=run(&mut slot_bank,g,|effect,reply|close.step_into(4096,effect,reply));let work=u64::try_from(result.work).unwrap();assert!(work<=remaining.maximum_items as u64);remaining.maximum_items-=work as usize;let p=result.result.unwrap().progress();remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;remaining.maximum_release_bytes-=p.released_bytes;}
 assert!(close.terminal_is_empty());let mut issuer=crate::FactoryAuthority::new(factory);
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if issuer.terminal_is_empty(){break}let g=grant(issuer.demands(4096).unwrap());let turn=run(&mut slot_bank,g,|effect,reply|issuer.step_into(4096,effect,reply));assert!(turn.work<=remaining.maximum_items as u128);remaining.maximum_items-=turn.work as usize;let p=turn.result.unwrap().progress();remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;remaining.maximum_release_bytes-=p.released_bytes;}assert!(issuer.terminal_is_empty());
}

trait Progressed{fn progressed(&self)->RetainedCloneProgress;}
impl Progressed for crate::ValueError{fn progressed(&self)->RetainedCloneProgress{self.retained_progress()}}
impl Progressed for crate::OriginalRetirementFailure{fn progressed(&self)->RetainedCloneProgress{self.retained_progress()}}
struct PartialBank{remaining:RetainedCloneGrant,cpu:u64}
impl PartialBank{
 fn new(law:&serde_json::Value)->Self{Self{remaining:RetainedCloneGrant{maximum_items:law["itemStock"].as_u64().unwrap()as usize,maximum_copy_bytes:law["copyStock"].as_u64().unwrap()as usize,maximum_capacity_bytes:law["capacityStock"].as_u64().unwrap()as usize,maximum_release_bytes:law["releaseStock"].as_u64().unwrap()as usize,maximum_depth:law["maximumDepth"].as_u64().unwrap()as usize},cpu:law["cpuStock"].as_u64().unwrap()}}
 fn grant(&self,d:RetirementDemand)->RetainedCloneGrant{let g=grant(d);assert!(self.cpu>0&&g.maximum_items<=self.remaining.maximum_items&&g.maximum_copy_bytes<=self.remaining.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.remaining.maximum_capacity_bytes&&g.maximum_release_bytes<=self.remaining.maximum_release_bytes&&g.maximum_depth<=self.remaining.maximum_depth);g}
 fn post<E:std::fmt::Debug+Progressed>(&mut self,turn:crate::RetainedWorkOutcome<crate::RetainedCloneStep,E>,heap:(usize,usize),g:RetainedCloneGrant){self.cpu=self.cpu.checked_sub(u64::try_from(turn.work).unwrap()).unwrap();let p=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.progressed()};assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.remaining.maximum_items=self.remaining.maximum_items.checked_sub(p.copied_items).unwrap();self.remaining.maximum_copy_bytes=self.remaining.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.remaining.maximum_capacity_bytes=self.remaining.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.remaining.maximum_release_bytes=self.remaining.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();turn.result.unwrap();}
}
static PARTIAL_RETIRED_POINTER:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
#[derive(semio_framework_value_factory::FactoryPayloadRetirement)]
#[value(crate="semio_framework_value_factory")]
struct PartialIssuer;
impl ArtifactOwnedValueRetirementFactory<String> for PartialIssuer{
 fn retirement_birth_bytes(&self,value:&String)->usize{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retirement_birth_bytes(value)}
 fn retire_owned_work_demand(&self,value:&String)->Result<u64,crate::ValueError>{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retire_owned_work_demand(value)}
 fn retire_owned_demands(&self,value:&String)->Result<RetirementDemand,crate::ValueError>{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retire_owned_demands(value)}
 fn retire_owned<'reply>(&self,value:&mut Option<String>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_factory::FactoryProducerReply<'reply,dyn crate::ErasedSnapshotRetirement,crate::OriginalRetirementFailure>)->semio_framework_value_factory::FactoryProducerReplyComplete<'reply,crate::OriginalRetirementFailure>{if let Some(value)=value.as_ref(){PARTIAL_RETIRED_POINTER.store(value.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed)}semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().retire_owned(value,effect,reply)}
 fn recover_retire_owned<'reply>(&self,value:&mut Option<String>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_factory::FactoryProducerReply<'reply,dyn crate::ErasedSnapshotRetirement,crate::OriginalRetirementFailure>)->semio_framework_value_factory::FactoryProducerReplyComplete<'reply,crate::OriginalRetirementFailure>{semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default().recover_retire_owned(value,effect,reply)}
}
#[test]
fn every_partial_source_admission_returns_the_same_slot_payload_through_its_captured_issuer(){
 let mut slot_bank=scratch();
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}
 for cut in law["sourceAdmissionCuts"].as_array().unwrap(){PARTIAL_RETIRED_POINTER.store(0,std::sync::atomic::Ordering::Relaxed);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(PartialIssuer);let mut slot=RetainedOriginalSlot::new(law["text"].as_str().unwrap().to_owned());let pointer=slot.get().as_ptr();let key=slot.key();let mut bank=PartialBank::new(&law);
  for _ in 0..law["sourceAdmissionBaseControls"].as_u64().unwrap()+cut.as_u64().unwrap(){let g=bank.grant(slot.demands(key,4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|slot.advance_read_into(key,&factory,effect,reply)));bank.post(turn,heap,g);assert_eq!(slot.get().as_ptr(),pointer);assert_eq!(slot.key(),key);}assert!(slot.has_read());assert!(slot.borrow(key).is_err());assert_eq!(serde_json::to_value(slot.get()).unwrap(),law["text"]);
  let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::retain(slot);
  for _ in 0..law["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let g=bank.grant(owner.next_demand(4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|owner.step_into(4096,effect,reply)));bank.post(turn,heap,g);}assert!(owner.terminal_is_empty());assert_eq!(PARTIAL_RETIRED_POINTER.load(std::sync::atomic::Ordering::Relaxed),pointer as usize);
  let mut issuer=crate::FactoryAuthority::new(factory);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if issuer.terminal_is_empty(){break}let g=bank.grant(issuer.demands(4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|issuer.step_into(4096,effect,reply)));bank.post(turn,heap,g);}assert!(issuer.terminal_is_empty());assert_eq!(crate::observe_retirement_allocations(||drop((owner,issuer))).1,(0,0));
 }
}

#[test]
fn original_read_return_start_is_a_distinct_denied_or_paid_zero_heap_control(){
 let mut slot_bank=scratch();
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let mut bank=PartialBank::new(&law);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value_factory::OwnedValueRetirementFactory::<String>::default());let mut slot=RetainedOriginalSlot::new(law["text"].as_str().unwrap().to_owned());let pointer=slot.get().as_ptr();let key=slot.key();let g=bank.grant(slot.demands(key,4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|slot.advance_read_into(key,&factory,effect,reply)));bank.post(turn,heap,g);assert!(slot.has_read());
 let expected=RetirementDemand{copy_bytes:law["returnStart"]["copyBytes"].as_u64().unwrap()as usize,capacity_bytes:law["returnStart"]["capacityBytes"].as_u64().unwrap()as usize,release_bytes:law["returnStart"]["releaseBytes"].as_u64().unwrap()as usize,depth:law["returnStart"]["depth"].as_u64().unwrap()as usize};assert_eq!(slot.return_demands(key,4096).unwrap(),expected);let g=bank.grant(expected);let mut returned=None;
 for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,denied,|effect,reply|slot.return_read_into(key,&mut returned,effect,reply)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert!(slot.has_read());assert!(returned.is_none());assert_eq!(slot.get().as_ptr(),pointer);assert_eq!(slot.return_demands(key,4096).unwrap(),expected);}
 let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|slot.return_read_into(key,&mut returned,effect,reply)));assert_eq!(turn.work,u128::from(law["returnStart"]["work"].as_u64().unwrap()));assert_eq!(heap,(0,0));let p=turn.result.as_ref().unwrap().progress();assert_eq!(p,RetainedCloneProgress{copied_items:1,copied_bytes:expected.copy_bytes,..Default::default()});bank.post(turn,heap,g);assert!(slot.has_read());assert!(returned.is_none());assert_eq!(slot.get().as_ptr(),pointer);
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if !slot.has_read(){break}let g=bank.grant(slot.return_demands(key,4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|slot.return_read_into(key,&mut returned,effect,reply)));bank.post(turn,heap,g);}assert!(!slot.has_read());assert!(bank.remaining.maximum_release_bytes<usize::try_from(law["releaseStock"].as_u64().unwrap()).unwrap());assert_eq!(slot.get().as_ptr(),pointer);assert_eq!(serde_json::to_value(slot.get()).unwrap(),law["text"]);let mut returned_issuer=crate::FactoryAuthority::new(returned.take().unwrap());let mut original_issuer=crate::FactoryAuthority::new(factory);
 let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,Default::default(),|effect,reply|slot.return_read_into(key,&mut returned,effect,reply)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));
 let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::retain(slot);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let g=bank.grant(owner.next_demand(4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|owner.step_into(4096,effect,reply)));bank.post(turn,heap,g);}assert!(owner.terminal_is_empty());for issuer in [&mut returned_issuer,&mut original_issuer]{for _ in 0..law["maximumTurns"].as_u64().unwrap(){if issuer.terminal_is_empty(){break}let g=bank.grant(issuer.demands(4096).unwrap());let(turn,heap)=crate::observe_retirement_allocations(||run(&mut slot_bank,g,|effect,reply|issuer.step_into(4096,effect,reply)));bank.post(turn,heap,g);}assert!(issuer.terminal_is_empty());}assert_eq!(crate::observe_retirement_allocations(||drop((owner,returned_issuer,original_issuer))).1,(0,0));
}
